ALTER TABLE "business_foundation_entry" DROP CONSTRAINT "business_foundation_entry_pair";--> statement-breakpoint
ALTER TABLE "business_foundation_entry" ADD CONSTRAINT "business_foundation_entry_lineup" CHECK ("business_foundation_entry"."kind" <> 'lineup' or ((jsonb_typeof("business_foundation_entry"."payload"->'lineup') = 'array' and jsonb_array_length("business_foundation_entry"."payload"->'lineup') between 1 and 20 and jsonb_array_length("business_foundation_entry"."payload"->'lineup') = jsonb_array_length(jsonb_path_query_array("business_foundation_entry"."payload", 'strict $.lineup[*] ? (@.name like_regex "^.{1,60}$" flag "s" && @.hex like_regex "^#[0-9A-F]{6}$")', '{}', true))) is true));--> statement-breakpoint
ALTER TABLE "business_foundation_entry" ADD CONSTRAINT "business_foundation_entry_pair" CHECK (("business_foundation_entry"."node", "business_foundation_entry"."kind") in (('identity-frame', 'given'), ('identity-frame', 'skipped'), ('architecture', 'answered'), ('name', 'given'), ('core-idea', 'written'), ('core-idea', 'skipped'), ('competitive-frame', 'lineup')));